contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint beforeBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint afterAddBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        c.withdrawBalance(); if (__ESBMC_reverted()) return;

        uint afterFirstWithdrawBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        c.withdrawBalance(); if (__ESBMC_reverted()) return;

        uint afterSecondWithdrawBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        assert(
            afterAddBal == beforeBal + amount &&
            afterFirstWithdrawBal == 0 &&
            afterSecondWithdrawBal == 0 &&
            address(c).balance == cBalBefore
        );
    }

    receive() external payable {}
}

