pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeBal;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        uint cBalBefore = address(c).balance;
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 afterAddBal;
        try c.getBalance(address(this)) returns (uint256 __r) { afterAddBal = __r; } catch { return; }
        try c.withdrawBalance() {} catch { return; }
        uint256 afterFirstWithdrawBal;
        try c.getBalance(address(this)) returns (uint256 __r) { afterFirstWithdrawBal = __r; } catch { return; }
        try c.withdrawBalance() {} catch { return; }
        uint256 afterSecondWithdrawBal;
        try c.getBalance(address(this)) returns (uint256 __r) { afterSecondWithdrawBal = __r; } catch { return; }
        assertTrue(afterAddBal == beforeBal + amount &&
            afterFirstWithdrawBal == 0 &&
            afterSecondWithdrawBal == 0 &&
            address(c).balance == cBalBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
